    }

    @Test
    void corporateTecnosul12PercentOff() {
        Room deluxe = new Rooms().find(201).orElseThrow();
        Price price = calculator.calculate(
                deluxe, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "TECNOSUL");

        // 2 nights of 389.90 = 779.80
        assertEquals(new BigDecimal("779.80"), price.subtotal());
        assertEquals(new BigDecimal("93.58"), price.discount());
        assertEquals(new BigDecimal("686.22"), price.total());
    }

    @Test
    void corporateAgrovale18PercentOff() {
        Price price = calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 13), RatePlan.CORPORATE, "AGROVALE");

        // 3 nights of 249.90 = 749.70
        assertEquals(new BigDecimal("749.70"), price.subtotal());
        assertEquals(new BigDecimal("134.95"), price.discount());
        assertEquals(new BigDecimal("614.75"), price.total());
    }

    @Test
    void corporateFarmavida25PercentOff() {
        Price price = calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "FARMAVIDA");

        assertEquals(new BigDecimal("499.80"), price.subtotal());
        assertEquals(new BigDecimal("124.95"), price.discount());
        assertEquals(new BigDecimal("374.85"), price.total());
    }

    @Test
    void corporateRequiresValidCompanyCode() {
        HotelException ex = assertThrows(HotelException.class, () -> calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, null));
        assertEquals(ErrorCode.INVALID_REQUEST, ex.errorCode());

        ex = assertThrows(HotelException.class, () -> calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "INVALID"));
        assertEquals(ErrorCode.INVALID_REQUEST, ex.errorCode());
    }

    @Test
    void weekendPackageHasFixedPriceByRoomType() {
        Room deluxe = new Rooms().find(201).orElseThrow();
        // Friday March 12, 2027 to Sunday March 14, 2027
        Price price = calculator.calculate(
                deluxe, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14), RatePlan.WEEKEND_PACKAGE, null);

        assertEquals(2, price.nights());
        assertEquals(new BigDecimal("820.00"), price.subtotal());
        assertEquals(new BigDecimal("0.00"), price.discount());
        assertEquals(new BigDecimal("820.00"), price.total());
    }

    @Test
    void weekendPackageRequiresFridayToSunday() {
        HotelException ex = assertThrows(HotelException.class, () -> calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.WEEKEND_PACKAGE, null));
        assertEquals(ErrorCode.INVALID_REQUEST, ex.errorCode());
    }

    @Test
    void weekendPackageRequiresExactlyTwoNights() {
        // Friday to Saturday is only 1 night
        HotelException ex = assertThrows(HotelException.class, () -> calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 13), RatePlan.WEEKEND_PACKAGE, null));
        assertEquals(ErrorCode.INVALID_REQUEST, ex.errorCode());

        // Friday to Monday is 3 nights
        ex = assertThrows(HotelException.class, () -> calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 15), RatePlan.WEEKEND_PACKAGE, null));
        assertEquals(ErrorCode.INVALID_REQUEST, ex.errorCode());
    }

    @Test
    void longStay10PercentOffFor7OrMoreNights() {
        Price price = calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 8), RatePlan.LONG_STAY, null);

        // 7 nights of 249.90 = 1749.30
        assertEquals(7, price.nights());
        assertEquals(new BigDecimal("1749.30"), price.subtotal());
        assertEquals(new BigDecimal("174.93"), price.discount());
        assertEquals(new BigDecimal("1574.37"), price.total());
    }

    @Test
    void longStayRequiresAtLeast7Nights() {
        HotelException ex = assertThrows(HotelException.class, () -> calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 7), RatePlan.LONG_STAY, null));
        assertEquals(ErrorCode.INVALID_REQUEST, ex.errorCode());
    }

    @Test
    void longStayDiscountAppliesWithHighSeason() {
        // 7 nights in high season (January)
        Price price = calculator.calculate(
                standardRoom, LocalDate.of(2027, 1, 10), LocalDate.of(2027, 1, 17), RatePlan.LONG_STAY, null);

        // 7 nights of (249.90 + 20%) = 7 * 299.88 = 2099.16
        assertEquals(new BigDecimal("2099.16"), price.subtotal());
        // 10% discount = 209.92
        assertEquals(new BigDecimal("209.92"), price.discount());
        assertEquals(new BigDecimal("1889.24"), price.total());
    }
}

